// GENERATED by scripts/import-products.mjs from products.xlsx.
// Do not hand-edit: names, counts and photos all come from the price list.
// `count` is baked from the same import that produces products.json;
// tests/routes/catalog-contract.test.ts fails the build if the two ever drift.
// This module must never import the product dataset (client bundle size).

export interface BrandEntry {
  /** Brand exactly as the price list spells it. */
  name: string;
  /** URL-safe form of `name`. */
  slug: string;
  /** Listings the price list really attributes to this brand. */
  count: number;
  /** A real photo from this brand's own listings (empty when it has none). */
  image: string;
}

